package com.bank.queue.model;

import java.math.BigDecimal;

public class PaymentRequest {
    private final String paymentId;
    private final String fromAcct;
    private final String toAcct;
    private final BigDecimal amount;
    private final long deadlineEpochMs; // after this, result is useless

    public PaymentRequest(String id, String from, String to, BigDecimal amt, long deadline) {
        this.paymentId = id; this.fromAcct = from; this.toAcct = to;
        this.amount = amt; this.deadlineEpochMs = deadline;
    }
    public String getPaymentId() { return paymentId; }
    public String getFromAcct() { return fromAcct; }
    public BigDecimal getAmount() { return amount; }
    public boolean isExpired() { return System.currentTimeMillis() > deadlineEpochMs; }
}
