package com.bank.queue.worker;

import com.bank.queue.model.PaymentRequest;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Logger;

// Demonstrates bounded vs unbounded behaviour with one switch.
public class PaymentProcessor {
    private static final Logger log = Logger.getLogger(PaymentProcessor.class.getName());
    private final ThreadPoolExecutor pool;
    private final AtomicLong accepted = new AtomicLong();
    private final AtomicLong shed = new AtomicLong();
    private final AtomicLong expiredDropped = new AtomicLong();

    public PaymentProcessor(int workers, int boundedCapacity) {
        // boundedCapacity <= 0 means UNBOUNDED (dangerous). Otherwise a bounded queue.
        BlockingQueue<Runnable> q = (boundedCapacity <= 0)
                ? new LinkedBlockingQueue<>()                 // UNBOUNDED: stores overload
                : new LinkedBlockingQueue<>(boundedCapacity); // BOUNDED: sheds overload
        this.pool = new ThreadPoolExecutor(workers, workers, 0L, TimeUnit.MILLISECONDS, q,
                new ThreadPoolExecutor.AbortPolicy());        // reject when bounded queue is full
    }

    public void submit(PaymentRequest req) {
        try {
            pool.execute(() -> {
                if (req.isExpired()) {                        // deadline-aware shedding
                    expiredDropped.incrementAndGet();
                    log.fine(() -> "Dropped expired payment " + req.getPaymentId());
                    return;                                    // do not waste capacity on dead work
                }
                settle(req);
                accepted.incrementAndGet();
            });
        } catch (RejectedExecutionException full) {
            shed.incrementAndGet();                            // explicit load shedding → 503
            log.warning(() -> "SHED 503 payment " + req.getPaymentId() + " (queue full)");
        }
    }

    private void settle(PaymentRequest req) {
        try { Thread.sleep(50); } catch (InterruptedException ignored) {} // slow worker
    }
    public long accepted() { return accepted.get(); }
    public long shed() { return shed.get(); }
    public long expiredDropped() { return expiredDropped.get(); }
    public int queueDepth() { return pool.getQueue().size(); }
    public void shutdown() throws InterruptedException {
        pool.shutdown(); pool.awaitTermination(30, TimeUnit.SECONDS);
    }
}
