package com.bank.queue;

import com.bank.queue.model.PaymentRequest;
import com.bank.queue.worker.PaymentProcessor;
import java.math.BigDecimal;
import java.util.logging.*;

public class QueueDemo {
    private static final Logger log = Logger.getLogger(QueueDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.INFO);
    }
    public static void main(String[] args) throws Exception {
        log.info("=== UNBOUNDED queue (dangerous) ===");
        runBurst(0);   // 0 → unbounded

        log.info("=== BOUNDED queue + load shedding (safe) ===");
        runBurst(20);  // cap at 20
    }

    private static void runBurst(int cap) throws InterruptedException {
        PaymentProcessor p = new PaymentProcessor(4, cap);
        long deadline = System.currentTimeMillis() + 500; // 500ms client deadline
        for (int i = 1; i <= 200; i++) {                   // burst far above service rate
            p.submit(new PaymentRequest("PAY" + i, "SAV2001", "CUR3001",
                    new BigDecimal("1000"), deadline));
        }
        int peakDepth = p.queueDepth();
        p.shutdown();
        log.info(() -> "accepted=" + p.accepted() + " shed=" + p.shed()
                + " expiredDropped=" + p.expiredDropped() + " peakQueueDepth=" + peakDepth);
    }
}

